; NOTE: comments marked [AI] are machine-generated by claude-opus-4-8 from the code alone
; and may be inaccurate; treat them as hints, not verified annotation. Comments marked
; [DOC <manual> <page>] have been reconciled against the primary-source Microsoft SoftCard
; manuals (CP/M 2.20, (C) 1980) and are authoritative: S&HD = "Software and Hardware
; Details", CPMREF = the CP/M 2.2 Reference Manual. See the consolidated fact sheet at
; ../../docs/CPM_Manual_Reconcile_Facts.md. SCOPE: this is the 2.23 BIOS in the 60K config.
; The SoftCard I/O facts (config block, I/O Vector Table, Card Type Table, RPC cells) are
; SHARED across releases and carry the manual's 2.20 addresses unchanged. The 60K memory
; map / load addresses ($FA00 ORG, the $D300/$DCxx BDOS, etc.) are a POST-1980 config the
; manual does NOT document (it covers 44K and 56K only), so 60K-specific absolute addresses
; are flagged as outside the manual rather than cited to it; the device-6 / Pascal-1.1 probe
; is likewise a post-1980 extension absent from the 2.20 manual.

; Generated by disasm_z80
; Range:  $FA00-$FFFF  (1536 bytes)
;
; ===========================================================================
; 60K BIOS  -- the UNPATCHED TEMPLATE as shipped inside CPM60.COM
; ===========================================================================
; This is the BIOS exactly as it sits in the CPM60.COM installer payload (COM
; offset 0x2600, ORG $FA00) and on the disk's system tracks. It is the canonical
; *source* form: assembling it reproduces those 1536 bytes byte-for-byte, and it
; is the BIOS input to the CPM60.COM build.
;
; It is NOT quite what a booted image shows. The 6502 boot loader only COPIES the
; BIOS into the Language Card; it does not patch it. Instead the Z-80 cold-boot
; routine BIOS_BOOT ($FEEA) runs ONCE at cold start and self-modifies ~a few dozen
; bytes -- most visibly NOP-ing the $FA00 cold-boot JP here (JP BIOS_BOOT), since
; on the 60K system cold start is driven from the planted Z-80 reset; it also
; binds the console/RPC vectors ($FB37/$FCB9/$FB4A) to the installed card type.
; After it runs, the one-shot cold-boot region ($FEEA-$FF8D) is dead and the
; running system reuses it as scratch (so a captured snapshot shows ~147 bytes of
; $E5/$FF fill there -- those are NOT patches). What each self-mod does and why is
; catalogued in ../BOOT_AND_PATCHING.md section 3c. (BDOS is byte-identical in COM
; and booted; the CCP's only delta was the private-stack scratch at $DB5C.)
; ===========================================================================

    IFNDEF CPM60_LINK  ; [link] master defines CPM60_LINK and owns this; standalone keeps it
    DEVICE NOSLOT64K
    ENDIF

; -- External symbols --
WBOOTV            EQU $0000               ; Warm-boot vector — JP WBOOT in BIOS. Touching it causes a CP/M warm boot.
IOBYTE_ADDR               EQU $0003               ; [DOC S&HD 2-18] IOBYTE_ADDR: logical-to-physical device map at $0003 -- four 2-bit fields,
                                              ; CONSOLE (bits 0-1), READER (bits 2-3), PUNCH (bits 4-5), LIST (bits 6-7); set via STAT or
                                              ; BDOS funcs 7/8. Each field's value selects which I/O Vector Table entry (#1 vs #2) is used.
CDISK_ADDR                EQU $0004               ; Current drive (low nibble: 0=A, 1=B, ..., 15=P) and current user (high nibble, 0-15).
BDOS             EQU $0005               ; BDOS call vector — JP BDOS_ENTRY. Programs use CALL $0005 to invoke BDOS. Word at $0006 is also the top-of-TPA marker.
TBUFF          EQU $0080               ; Default 128-byte DMA buffer. BDOS cold-init / DRV_ALLRESET (fn 13) set the DMA address here and WBOOT re-issues SETDMA($0080); sector/record I/O moves 128 bytes through it. At program load this same buffer doubles as the command tail: the first byte ($0080) holds the tail length (0-127) and the characters follow at $0081 (CMDLINE).
TPA            EQU $0100               ; Start of Transient Program Area. .COM files load here and execute starting at $0100.
SLOT_INFO_BASE       EQU $F3B8               ; [DOC S&HD 2-26/2-27] $F3B8 is the Disk Count Byte (number of disk controller cards x2);
                                              ; the Card Type Table (SLTTYP) proper starts at $F3B9, with slot S's entry at $F3B8+S
                                              ; (S=1..7). The cold-boot scan indexes this base by E (E=1..7) to read each slot's detected
                                              ; card type. Card type values: 0=no ROM, 1=unknown ROM, 2=Disk II, 3=Apple Comms/CCS 7710A
                                              ; serial, 4=Apple High-Speed Serial / Videx Videoterm / M&R Sup-R-Term / Silentype, 5=Parallel.


; -- Mid-instruction references (shown inline as cover+offset) --
;   $FB05 -> CCP_LAUNCH+1       z80 skip idiom: enters the operand of $3E at $FB04
;   $FB49 -> RPC_TRIGGER_STORE+1     shared instruction tail: $FB49 is reachable code inside the instruction at $FB48
;   $FEEB -> BIOS_BOOT+1          shared instruction tail: $FEEB is reachable code inside the instruction at $FEEA
;   $FEEC -> BIOS_BOOT+2          shared instruction tail: $FEEC is reachable code inside the instruction at $FEEA
;   $FEFA -> DISK_DMAADR+2        shared instruction tail: $FEFA is reachable code inside the instruction at $FEF8
;   $FEFC -> SECTOR_BLOCK_PATCH+1        shared instruction tail: $FEFC is reachable code inside the instruction at $FEFB
;   $FF59 -> BIOS_BOOT_13+1       shared instruction tail: $FF59 is reachable code inside the instruction at $FF58

    IFNDEF CPM60_LINK  ; [link] master defines CPM60_LINK and owns this; standalone keeps it
    ORG $FA00
    ENDIF

; ----------------------------------------------------------------------
; BIOS_VECTOR (BOOT) -- the CP/M 2.2 BIOS entry jump vector (2.23, 60K, $FA00).
;   15 three-byte JP entries the BDOS/CCP and the cold loader call by fixed
;   offset from the BIOS base: BOOT, WBOOT, CONST, CONIN, CONOUT, LIST, PUNCH,
;   READER, HOME, SELDSK, SETTRK, SETSEC, SETDMA, READ, WRITE.
;   In:  entered by JP/CALL to base+3*n.  Out: per the dispatched entry.
;   Note: 60K cold start is driven from the planted Z-80 reset; BIOS_BOOT ($FEEA)
;     NOP-s this $FA00 cold JP after its one run, so $FA03 (WBOOT) is the live
;     entry thereafter. See ../BOOT_AND_PATCHING.md section 3c. [RE]
; ----------------------------------------------------------------------
BOOT:
        JP BIOS_BOOT
WBOOT:
        JP BIOS_WBOOT
CONST:
        JP BIOS_CONST
CONIN:
        JP BIOS_CONIN
CONOUT:
        JP CONOUT_DISPATCH
LIST:
        JP BIOS_LIST
PUNCH:
        JP BIOS_PUNCH
READER:
        JP BIOS_READER
HOME:
        JP INIT_PASCAL_1_1_1
SELDSK:
        JP SELDSK_IMPL_1
SETTRK:
        JP SETTRK_STORE
SETSEC:
        JP BIOS_SETSEC
SETDMA:
        JP BIOS_SETDMA
READ:
        JP SELDSK_IMPL_3
WRITE:
        JP SELDSK_IMPL_4
; ----------------------------------------------------------------------
; LISTST -- entry 15: return the list device's ready status.
;   In:  none.  Out: A = $00.  Clobbers: A, flags.
;   Algorithm: XOR A / RET. A is $00 whatever the printer is doing. Under the
;     CP/M 2.2 convention $00 means NOT ready and $FF means ready, so this
;     reports "not ready" unconditionally.
;     That is the whole of what these two bytes support. WHO consults LISTST, and
;     what they do with the answer, is NOT determinable from this image, and the
;     SoftCard manual set in softcard/reference/ does not document LISTST at all
;     -- so no claim is made here about callers or about anything blocking. Same two bytes in the 2.20-44K and 2.23-44K twins. [RE]
; ----------------------------------------------------------------------
LISTST:
        XOR A
        RET
        DEFB    $00
; ----------------------------------------------------------------------
; SECTRAN -- logical-to-physical sector translate (no-op identity map).
;   In:  BC = logical sector, DE = translate-table addr (ignored).
;   Out: HL = BC (physical == logical).  Clobbers: HL.
;   Algorithm: LD H,B / LD L,C / RET.  The skew is applied off-image by the
;     disk producer, so the DPH XLT is null and SECTRAN is the identity. [RE]
; ----------------------------------------------------------------------
SECTRAN:
        LD H,B
        LD L,C
        RET
; ----------------------------------------------------------------------
; DPH_TABLE -- the CP/M 2.2 Disk Parameter Header array: one 16-byte DPH per logical
;   drive 0..3. SELDSK returns DPH_TABLE + 16*drive (SELDSK_IMPL_1, $FEA9).
;   Each DPH = XLT, three BDOS scratch words, DIRBUF, DPB, CSV, ALV. XLT = 0: no SECTRAN
;   translate (SECTRAN above is the identity; the disk producer applies the skew
;   off-image). All four drives share one DIRBUF and one DPB.
;   The per-drive strides are the DPB's own fields: CSV is CKS = 12 bytes, ALV is
;   DSM/8 + 1 = 139/8 + 1 = 18 bytes. [RE]
; ----------------------------------------------------------------------
DPH_TABLE:
        DEFW    0,0,0,0,DIRBUF,DPB,CSV_VECTORS,   ALV_VECTORS ; drive 0
        DEFW    0,0,0,0,DIRBUF,DPB,CSV_VECTORS+12,ALV_VECTORS+18 ; drive 1
        DEFW    0,0,0,0,DIRBUF,DPB,CSV_VECTORS+24,ALV_VECTORS+36 ; drive 2
        DEFW    0,0,0,0,DIRBUF,DPB,CSV_VECTORS+36,ALV_VECTORS+54 ; drive 3
; DPB -- the shared Disk Parameter Block; all four DPH entries above point here (the
;   $73,$FA pointer byte pair in each). Byte-for-byte the same 15 bytes as the 2.23-44K
;   twin's DPB, DSM included. Field names are Digital Research's CP/M 2.2 DPB names.
;   Not [DOC]-citable from THIS archive -- the SoftCard set bundles DRI's CP/M 2.2
;   *Reference Manual*, which documents only BDOS fn 31 (the call that RETURNS a DPB
;   pointer), not the block's layout. The layout IS normatively specified by a DRI manual
;   not in the box: the CP/M 2.2 *Alteration Guide* (1979), sec. Disk Parameter Tables.
;   SoftCard CP/M is licensed DRI CP/M 2.2, so that manual governs this block.
;   [DOC CPMAG "Disk Parameter Tables"]  NOTE: the Guide defines every field but NEVER
;   spells the acronyms out; the expansions below are the conventional readings. [?]
DPB:
SPT:    DEFW    $0020                    ; Sectors Per Track: counts 128-byte RECORDS, not 256-byte sectors -> 32
BSH:    DEFB    $03                      ; Block SHift: log2(records per block) -> 8 records
BLM:    DEFB    $07                      ; BLock Mask: (records per block) - 1 -> 1 KB blocks
EXM:    DEFB    $00                      ; EXtent Mask
DSM:    DEFW    $008B                    ; Disk Size Max: highest allocation block number: 139 -> 140 blocks
DRM:    DEFW    $002F                    ; DiRectory Max: highest directory entry number: 47 -> 48 entries
AL0:    DEFB    $C0                      ; ALlocation bitmap, directory-reserved blocks, high byte -> 2
AL1:    DEFB    $00                      ; ditto, low byte
CKS:    DEFW    $000C                    ; ChecKSum: directory checksum bytes
OFF:    DEFW    $0003                    ; OFFset: reserved tracks before the file area
; [DOC S&HD 2-26/2-27] Cold-boot per-device init loop over the Card Type Table. The Card Type
;       Table (SLTTYP) starts at $F3B9, entry = $F3B8+S for slot S; $F3B8 itself is the Disk Count
;       Byte. The loop walks $F3B8+DE (DE=7..1 -> $F3BF..$F3B9), reading each slot's detected card
;       type and dispatching on it. (This is NOT the IOBYTE_ADDR table -- IOBYTE_ADDR is a single byte at $0003.)
; ----------------------------------------------------------------------
; PROBE_DEVICES -- cold/warm-boot per-device init loop over the Card Type Table.
;   In:  none (walks the SoftCard Card Type Table at z80 $F3B8..).
;   Out: config cells updated in place; each present card's init is called.
;   Clobbers: A,DE,HL.
;   Algorithm: for E = 7 down to 1, read SLTTYP[$F3B8+E]. Value 3 (serial) runs
;     SLOT_IO_ADDR then stamps the cell $03/$15; value 4 (Videx-class 80-col)
;     runs INIT_PASCAL_1_0 and reclaims the $C800 expansion-ROM window via
;     RPC_TRIGGER; value 6 (post-1980 Pascal-1.1 class) runs PLOT_CHAR_RPC
;     with the $0DD0 param. [DOC S&HD 2-26/2-27] SLTTYP base at $F3B9, entry
;     $F3B8+S; $F3B8 is the Disk Count Byte. Twin of the 2.23-44K PROBE_DEVICES. [RE]
; ----------------------------------------------------------------------
PROBE_DEVICES:
        LD DE,$0007
; [DOC S&HD 2-26] Loop body: reads the slot's Card Type Table value at $F3B8+DE. Card type 3
;       (Apple Communications / CCS 7710A serial) runs its init and stamps the entry; card type 4
;       (Apple High-Speed Serial / Videx Videoterm / M&R Sup-R-Term) takes the decremented branch
;       below that reclaims the $C800 firmware window.
SLOT_SCAN_INIT_1:
        LD HL,SLOT_INFO_BASE
        ADD HL,DE
        LD A,(HL)
        SUB $03
        JR NZ,PROBE_DEVICES_CHK4
        CALL SLOT_IO_ADDR
        LD (HL),$03
        LD (HL),$15
; [DOC S&HD 2-26] Card-type-4 branch (Apple High-Speed Serial / Videx Videoterm / M&R Sup-R-Term):
;       runs INIT_PASCAL_1_0, then reclaims the shared $C800 expansion-ROM window (LD HL,$C800)
;       before continuing the per-slot Card Type Table scan. The card-type-2 sub-branch below
;       ($FAA3, CP $02 -> type-6) is the post-1980 Pascal-1.1 path NOT documented by the 2.20 manual.
PROBE_DEVICES_CHK4:
        DEC A
        JR NZ,SLOT_SCAN_INIT_3
        CALL INIT_PASCAL_1_0
        LD HL,$C800
        CALL RPC_TRIGGER
        JR PROBE_DEVICES_NEXT
; [AI] Card-type dispatch continuation: after SUB $03 then DEC A, a remaining value of $02 means the
;       original Card Type Table byte was 6 -- the POST-1980 device-6 / Pascal-1.1 card class that
;       the 2.20 manual does NOT document (2.23 added a $Cn0B Pascal-1.1 probe that reassigns the
;       Videx from type 4 to type 6). Runs PLOT_CHAR_RPC with the $0DD0 parameter. Not manual-backed.
SLOT_SCAN_INIT_3:
        CP $02
        JR NZ,PROBE_DEVICES_NEXT
        LD HL,$0DD0
        CALL PLOT_CHAR_RPC
; [DOC S&HD 2-26/2-27] Loop tail of the Card Type Table scan: decrements the slot index E and repeats
;       for all seven Apple expansion slots (S=7..1), returning when done.
PROBE_DEVICES_NEXT:
        DEC E
        JR NZ,SLOT_SCAN_INIT_1
        RET
; ----------------------------------------------------------------------
; SLOT_E000_ADDR -- form a SoftCard I/O address from a device/offset index.
;   In:  E = low offset within the I/O page.  A clobbered.
;   Out: HL = ((E | $E0) << 8) -- an address in z80 $E000-$EFFF = Apple $C000-$CFFF.
;   Algorithm: H = $E0 base; A = E OR H forces the high nibble into the $C0xx I/O
;     page; H = A.  Used to reach keyboard / soft switches / slot I/O.  Twin of the
;     2.23-44K DEVICE_IO_BASE. [RE]
; ----------------------------------------------------------------------
SLOT_E000_ADDR:
        LD HL,$E000
        LD A,E
        OR H
        LD H,A
RET_VECTOR:
        RET
; [AI] WBOOT (warm boot) entry: resets the Z-80 stack to $0080, re-establishes the 6502 console via
;       RPC, rescans the slots, then reloads/relaunches the CCP. NOTE: the BDOS sentinel at $DC08
;       and BDOS entry $DC06 are 60K-config absolute addresses -- a POST-1980 layout the 2.20 manual
;       (44K/56K only) does NOT document; do not read a manual address into them.
; ----------------------------------------------------------------------
; BIOS_WBOOT (WBOOT) -- CP/M warm boot: re-init console, rebuild page zero, re-enter CCP.
;   In:  none.  Out: does not return (enters the CCP at $D300).  Clobbers: all.
;   Algorithm: SP = default DMA top ($0080); touch the 80-col soft switch (z80 $E051
;     = Apple $C051 TXTSET); re-init the console via RPC_TRIGGER; re-run PROBE_DEVICES.
;     Test the resident BDOS sentinel at $DC08 ($DC present = BDOS image intact) to skip
;     the reload; otherwise reload the system through a self-built $000B page-zero bridge.
;   Note: 60K addresses ($DC06/$DC08 BDOS, $D307/$D74E CCP scratch, CCP entry $D300) are
;     the POST-1980 Language-Card layout the 2.20 manual (44K/56K only) does NOT document;
;     do not read a manual address into them. Twin of the 2.23-44K WBOOT (there $9C08/$9300). [RE]
; ----------------------------------------------------------------------
BIOS_WBOOT:
        LD SP,TBUFF
        LD A,($E051)
        LD HL,$0E00
        CALL RPC_TRIGGER
        CALL PROBE_DEVICES
        LD A,($DC08)
        CP $DC
        JR Z,PAGEZERO_REBUILD
; [DOC S&HD 2-24/2-25] Warm-boot RPC setup: stores the 6502 call target at A$VEC=$F3D0, then loads
;       the SoftCard location from Z$CPU=$F3DE (low byte 0, high byte $0ENH for slot N) -- a WRITE
;       through that address is the CPU switch back to the 6502. ($000B/$77 here is 60K-specific glue.)
        LD HL,BIOS_BOOT_13+1
        LD ($F3D0),HL
        LD HL,($F3DE)
        LD A,$77
        LD ($000B),A
        JP $000B
PAGEZERO_REBUILD:
        XOR A
        LD ($D307),A
; [AI] Cold-boot page-zero plant: writes JP WBOOT at $0000-$0002 and JP BDOS at $0005-$0007 (the
;       $0000 warm-boot vector and $0005 BDOS entry are SHARED CP/M architecture). The BDOS target
;       $DC06 stored at $0006 -- which also marks top-of-TPA -- is a 60K-config absolute address;
;       the 2.20 manual (44K/56K only) does NOT document this POST-1980 layout, so it is not cited.
; ----------------------------------------------------------------------
; PAGEZERO_REBUILD_HOOKS -- rebuild page zero, then fall into the CCP relaunch.
;   In:  none.  Out: falls into CCP_LAUNCH (CCP entry).  Clobbers: A,HL,BC.
;   Algorithm: plant JP ($C3) at $0000 -> WBOOT (BIOS $FA03) and JP at $0005 -> BDOS
;     ($DC06); clear the two self-modified cold-boot template cells (BOOT_TMPL_IOBYTE/
;     DISK_HSTACT); re-issue SETDMA($0080). The $0000 warm-boot vector and $0005 BDOS
;     entry are SHARED CP/M architecture; the BDOS target $DC06 (also the top-of-TPA
;     marker at $0006) is a 60K-config absolute address, not manual-backed. Twin of
;     the 2.23-44K PAGEZERO_REBUILD_HOOKS. [RE]
; ----------------------------------------------------------------------
PAGEZERO_REBUILD_HOOKS:
        XOR A
        LD (BOOT_TMPL_IOBYTE),A
        LD (DISK_HSTACT),A
        LD A,$C3
        LD (WBOOTV),A
        LD HL,WBOOT
        LD ($0001),HL
        LD (BDOS),A
        LD HL,$DC06
        LD ($0006),HL
        LD BC,TBUFF
        CALL BIOS_SETDMA
; ----------------------------------------------------------------------
; CCP_LAUNCH -- final warm/cold-boot tail: set the CCP entry flag, enter the CCP.
;   In:  none.  Out: JP $D300 (CCP entry); no return.  Clobbers: A,C.
;   Algorithm: store a CCP-mode flag ($01) into $D74E (self-modified operand at
;     CCP_LAUNCH+1), pass the current default drive (CDISK_ADDR, $0004) in C, and jump
;     to the 60K CCP at $D300 (the 44K twin CCP_LAUNCH entered $9300). [RE]
; ----------------------------------------------------------------------
CCP_LAUNCH:
        LD A,$01
        LD ($D74E),A
        LD A,(CDISK_ADDR)
        LD C,A
        JP $D300
; [DOC S&HD 2-18/2-19] CONST (console status) BIOS entry: jumps through I/O Vector Table cell 1,
;       $F380 (Console Status) -- the routine returns A=$FF if a console character is ready, $00
;       otherwise. This cell normally points into the BIOS and is user-patchable.
; ----------------------------------------------------------------------
; BIOS_CONST (CONST) -- CP/M console status: A=$FF if a char is ready, else $00.
;   In:  none.  Out: A=$FF (ready)/$00 (not).  Clobbers: A,HL.
;   Algorithm: load the console-status handler from the SoftCard I/O Vector Table
;     Console Status cell (z80 $F380 = Apple $0380) and JP (HL) to the 6502-serviced
;     handler, which returns the status in A. This cell is user-patchable.
;     [DOC S&HD 2-18/2-19] Twin of the 2.23-44K CONST. [RE]
; ----------------------------------------------------------------------
BIOS_CONST:
        LD HL,($F380)
        JP (HL)
        DEFB    $3A
CONST_VEC_PATCH:
        DEFB    $00,$E0,$17,$9F,$C9
; [DOC S&HD 2-17] CONIN (console input) BIOS entry: reads a raw key via CONIN_DISPATCH_IOBYTE, masks the
;       high bit (AND $7F), then walks the Keyboard Character Redefinition Table to translate it.
;       Per the manual the table is at $F3AC; the code seeds HL=$F3AB and INC HL's to the first
;       entry's "from" byte at $F3AC. Up to six 2-byte entries (from-ASCII, to-ASCII, both high bit
;       clear); a byte with the high bit set terminates early (the JP M exit). Applies to TTY:/CRT:.
; ----------------------------------------------------------------------
; BIOS_CONIN (CONIN) -- read a console character: dispatch, then remap the key.
;   In:  none.  Out: A = (translated) key.  Clobbers: A,B,C,HL.
;   Algorithm: CALL CONIN_DISPATCH_IOBYTE to fetch a raw key (routed by the IOBYTE_ADDR CONSOLE
;     field); AND $7F to 7-bit; then walk the Keyboard Character Redefinition Table.
;     Per the manual the table is at $F3AC; the code seeds HL=$F3AB and INC HL's to the
;     first entry. Up to six 2-byte entries (from-ASCII, to-ASCII); a high-bit-set byte
;     terminates early (JP M). On a match returns the redefined 'to' byte, else the raw
;     key. [DOC S&HD 2-17] Twin of the 2.23-44K CONIN remap wrapper. [RE]
; ----------------------------------------------------------------------
BIOS_CONIN:
        CALL CONIN_DISPATCH_IOBYTE
        AND $7F
        LD HL,$F3AB
        LD B,$06
        LD C,A
; [DOC S&HD 2-17] Keyboard-redefinition scan body: INC past to the "from" byte, test for the
;       high-bit-set terminator (JP M exits), else compare the input (in C) and on a match return
;       the redefined "to" byte (A=(HL)); loop up to six times via DJNZ.
KEY_REMAP_SCAN:
        INC HL
        LD A,(HL)
        INC HL
        OR A
        JP M,KBD_STROBE_CLEAR
        CP C
        LD A,(HL)
        RET Z
        DJNZ KEY_REMAP_SCAN
KBD_STROBE_CLEAR:
        LD A,C
        RET
        DEFB    $11,$03,$00,$C3
CONIN_HANDLER_VEC:
        DEFB    $39,$FB,$3A,$00,$E0,$17
        DEFW    SECTRAN
        DEFB    $32,$10,$E0,$3F,$1F,$C9
; [DOC S&HD 2-24/2-25] RPC dispatch: stores the 6502 subroutine address (in HL) at A$VEC=$F3D0
;       (low-high) -- the Z-80->6502 call vector -- before the SoftCard CPU-switch is triggered.
;       (The actual switch is a WRITE through Z$CPU=$F3DE; A$VEC just holds the target.)
; ----------------------------------------------------------------------
; RPC_TRIGGER -- fire a SoftCard 6502<->Z-80 RPC.
;   In:  HL = 6502 subroutine address; A = trigger value.  Out: per the 6502 service.
;   Algorithm: stash HL at A$VEC (z80 $F3D0 = Apple $03D0), the Z-80->6502 call vector,
;     then a store through the CPU-switch cell (RPC_TRIGGER_STORE) triggers the actual
;     switch. The store address (Z$CPU-derived) is self-modified at boot, so the store
;     site is RPC_TRIGGER_STORE+1. [DOC S&HD 2-24/2-25] Twin of the 2.23-44K RPC_TRIGGER. [RE]
; ----------------------------------------------------------------------
RPC_TRIGGER:
        LD ($F3D0),HL
RPC_TRIGGER_STORE:
        LD (WBOOTV),A
        RET
; ----------------------------------------------------------------------
; CONOUT_SET_C -- console-output entry that first saves the char into C.
;   In:  A = character to emit.  Out: none.  Clobbers: A,C,HL.
;   Algorithm: LD C,A, then fall into CONOUT_DISPATCH. The BIOS CONOUT jump-vector
;     entry ($FA0C) targets CONOUT_DISPATCH+1 (skipping this LD C,A) when C is already
;     set; callers that hold the char in A enter here instead. Twin of the 2.23-44K
;     CONOUT_DISPATCH LD C,A prologue. [RE]
; ----------------------------------------------------------------------
CONOUT_SET_C:
        LD C,A
; [DOC S&HD 2-18/2-19] CONOUT (console output) dispatch: masks the IOBYTE_ADDR CONSOLE field (bits 0-1).
;       Value 2 = BAT: (RDR: in / LST: out), so console output is routed through I/O Vector Table
;       List Output #1 ($F392); any other value falls through to the screen-function escape processor.
; ----------------------------------------------------------------------
; CONOUT_DISPATCH -- emit a console character, routed by the CP/M IOBYTE_ADDR.
;   In:  C = character (from CONOUT_SET_C; the +1 jump-vector entry skips the LD C,A).
;   Out: none.  Clobbers: A,C,HL.
;   Algorithm: read IOBYTE_ADDR ($0003), mask the 2-bit CONSOLE field (AND $03). Value 2 =
;     BAT: (RDR: in / LST: out), so output routes through I/O Vector Table List Output
;     #1 ($F392) via CONOUT_UC1; any other value falls into the screen-function escape
;     processor. [DOC S&HD 2-18/2-19] Twin of the 2.23-44K CONOUT_DISPATCH. [RE]
; ----------------------------------------------------------------------
CONOUT_DISPATCH:
        LD A,(IOBYTE_ADDR)
        AND $03
        CP $02
        JR NZ,CONOUT_ESC_PROC
; [DOC S&HD 2-18/2-19] Jumps through I/O Vector Table List Output #1 cell ($F392) -- used for the
;       BAT: console-output case above; the char in C is carried to the line-printer device.
; ----------------------------------------------------------------------
; CONOUT_UC1 -- console/list output via I/O Vector Table List Output #1 ($F392).
;   In:  C = character.  Out: none (JP (HL) into the handler).  Clobbers: A,HL.
;   Algorithm: load HL from the List Output #1 cell (z80 $F392 = Apple $0392) and
;     JP (HL). Used for the BAT: console-output case and the LPT: LIST case; the char
;     in C is carried to the line-printer device. [DOC S&HD 2-18/2-19] [RE]
; ----------------------------------------------------------------------
CONOUT_UC1:
        LD HL,($F392)
        JP (HL)
; [DOC S&HD 2-18/2-19] CONIN dispatch: masks the IOBYTE_ADDR CONSOLE field (bits 0-1). Value 2 (BAT:)
;       -> Reader Input #1 cell $F38A; value 3 (UC1:) -> Console Input #2 cell $F384; values 0/1
;       (TTY:/CRT:) -> Console Input #1 cell $F382. Each is a user-patchable I/O Vector Table cell.
; ----------------------------------------------------------------------
; CONIN_DISPATCH_IOBYTE -- read a console character, routed by the IOBYTE_ADDR CONSOLE field.
;   In:  none.  Out: A = character.  Clobbers: A,HL.
;   Algorithm: read IOBYTE_ADDR, mask the CONSOLE field (AND $03). Value 2 (BAT:) -> Reader
;     Input #1 cell $F38A; value 3 (UC1:) -> Console Input #2 cell $F384; values 0/1
;     (TTY:/CRT:) -> Console Input #1 cell $F382; then JP (HL). Each is a user-patchable
;     I/O Vector Table cell. Called by BIOS_CONIN and reused by BIOS_READER.
;     [DOC S&HD 2-18/2-19] Twin of the 2.23-44K CONIN_DISPATCH_IOBYTE. [RE]
; ----------------------------------------------------------------------
CONIN_DISPATCH_IOBYTE:
        LD A,(IOBYTE_ADDR)
        AND $03
        CP $02
        LD HL,($F384)
        JR Z,CONIN_UC1
        JR NC,CONIN_VEC_JP
; [DOC S&HD 2-18/2-19] TTY:/CRT: console input via I/O Vector Table Console Input #1 cell ($F382).
; ----------------------------------------------------------------------
; CONIN_TTY -- TTY:/CRT: console input via I/O Vector Table Console Input #1 ($F382).
;   In:  none.  Out: A = character (JP (HL) into the handler).  Clobbers: A,HL.
;   Algorithm: load HL from Console Input #1 (z80 $F382 = Apple $0382) and JP (HL).
;     Also the READER TTY:/CRT: target. [DOC S&HD 2-18/2-19] [RE]
; ----------------------------------------------------------------------
CONIN_TTY:
        LD HL,($F382)
        JP (HL)
; [DOC S&HD 2-18/2-19] BAT: console input via I/O Vector Table Reader Input #1 cell ($F38A).
; ----------------------------------------------------------------------
; CONIN_UC1 -- BAT:/PTR: input via I/O Vector Table Reader Input #1 ($F38A).
;   In:  none.  Out: A = character (falls into CONIN_VEC_JP -> JP (HL)).  Clobbers: A,HL.
;   Algorithm: load HL from Reader Input #1 (z80 $F38A = Apple $038A) and JP (HL) via
;     CONIN_VEC_JP. Reused by BIOS_READER for the PTR: case. [DOC S&HD 2-18/2-19] [RE]
; ----------------------------------------------------------------------
CONIN_UC1:
        LD HL,($F38A)
CONIN_VEC_JP:
        JP (HL)
; [DOC S&HD 2-18/2-19] LIST (printer) output: masks the IOBYTE_ADDR LIST field (bits 6-7; 0=TTY:, 1=CRT:,
;       2=LPT:, 3=UL1:). TTY:/CRT: return null; LPT: ($80) routes via CONOUT_UC1; UL1: ($C0) jumps
;       through the List Output #2 cell ($F394). (List Output #1 is $F392.) Char in C -> list device.
; ----------------------------------------------------------------------
; BIOS_LIST (LIST) -- printer output, routed by the IOBYTE_ADDR LIST field (bits 6-7).
;   In:  C = character.  Out: none.  Clobbers: A,HL.
;   Algorithm: read IOBYTE_ADDR, mask the LIST field (AND $C0). TTY:/CRT: (<$80) return null
;     (DISPATCH_NODEV); LPT: ($80) routes via CONOUT_UC1; UL1: ($C0) jumps through List
;     Output #2 ($F394). (List Output #1 is $F392.) [DOC S&HD 2-18/2-19] Twin of the
;     2.23-44K LIST. [RE]
; ----------------------------------------------------------------------
BIOS_LIST:
        LD A,(IOBYTE_ADDR)
        AND $C0
        CP $80
        JR C,DISPATCH_NODEV
        JR Z,CONOUT_UC1
        LD HL,($F394)
        JP (HL)
; [DOC S&HD 2-18/2-19] PUNCH output: masks the IOBYTE_ADDR PUNCH field (bits 4-5). Value 1 (PTP:) ->
;       Punch Output #1 cell ($F38E); higher values -> Punch Output #2 cell ($F390); value 0 (TTY:)
;       returns null. The char in C is sent to the selected paper-tape-punch device.
; ----------------------------------------------------------------------
; BIOS_PUNCH (PUNCH) -- punch output, routed by the IOBYTE_ADDR PUNCH field (bits 4-5).
;   In:  C = character.  Out: none.  Clobbers: A,HL.
;   Algorithm: read IOBYTE_ADDR, mask the PUNCH field (AND $30). TTY: (0) returns null
;     (DISPATCH_NODEV); PTP: ($10) -> Punch Output #1 ($F38E) via CONIN_VEC_JP; higher
;     values -> Punch Output #2 ($F390). The char in C goes to the paper-tape-punch
;     device. [DOC S&HD 2-18/2-19] Twin of the 2.23-44K PUNCH. [RE]
; ----------------------------------------------------------------------
BIOS_PUNCH:
        LD A,(IOBYTE_ADDR)
        AND $30
        CP $10
        JR C,DISPATCH_NODEV
        LD HL,($F38E)
        JR Z,CONIN_VEC_JP
        LD HL,($F390)
        JP (HL)
; [DOC S&HD 2-18/2-19] READER input: masks the IOBYTE_ADDR READER field (bits 2-3; 0=TTY:, 1=CRT:,
;       2=PTR:, 3=UR2:). TTY:/CRT: -> CONIN_TTY (console input); PTR: ($08) -> CONIN_UC1; UR2: ($0C)
;       jumps through the Reader Input #2 cell ($F38C). (Reader Input #1 is $F38A.) Char returned in A.
; ----------------------------------------------------------------------
; BIOS_READER (READER) -- reader input, routed by the IOBYTE_ADDR READER field (bits 2-3).
;   In:  none.  Out: A = character.  Clobbers: A,HL.
;   Algorithm: read IOBYTE_ADDR, mask the READER field (AND $0C). TTY:/CRT: (<$08) -> CONIN_TTY;
;     PTR: ($08) -> CONIN_UC1; UR2: ($0C) jumps through Reader Input #2 ($F38C). (Reader
;     Input #1 is $F38A.) [DOC S&HD 2-18/2-19] Twin of the 2.23-44K READER. [RE]
; ----------------------------------------------------------------------
BIOS_READER:
        LD A,(IOBYTE_ADDR)
        AND $0C
        CP $08
        JR C,CONIN_TTY
        JR Z,CONIN_UC1
        LD HL,($F38C)
        JP (HL)
; ----------------------------------------------------------------------
; DISPATCH_NODEV -- IOBYTE_ADDR field selects no physical device: fall into the filter.
;   In:  reached with carry set (no-device).  Out: enters the screen-function processor
;     (CONOUT_ESC_PROC) with the carry folded into a flag.  Clobbers: A,HL.
;   Algorithm: SCF, then CONOUT_ESC_PROC's SBC A,A turns carry into a 0/$FF flag stored
;     in COL_FLAG ($FEE4). Twin of the 2.23-44K DISPATCH_NODEV. [RE]
; ----------------------------------------------------------------------
DISPATCH_NODEV:
        SCF
; [DOC S&HD 2-14] Console-output screen-function processor. $F3A2 is the Hardware-table lead-in
;       character (zero = no lead-in). Reached for the non-BAT: console path; tests the lead-in to
;       decide whether a multi-byte screen-function sequence is being emitted.
; ----------------------------------------------------------------------
; CONOUT_ESC_PROC -- console-output screen-function / cursor-address processor.
;   In:  C = character; the SBC A,A flag from the caller.  Out: emits or updates cursor
;     state.  Clobbers: A,C,DE,HL.
;   Algorithm: store the entry flag in COL_FLAG ($FEE4). [DOC S&HD 2-14] $F3A2 is the
;     Hardware-table lead-in char (0 = none); if none, emit directly via CONSOLE_PUT_CHAR.
;     Else clear bit 7 of C; if the pending-column counter (COL_PENDING, $FEE5) is nonzero,
;     apply a config-driven column offset ($F396 = SXYOFF, the Software cursor XY offset,
;     high bit selecting X/Y vs Y/X order), else fall into the sequence scanner. Twin of
;     the 2.23-44K CONOUT_FILTER_NOEXPAND path. [RE]
; ----------------------------------------------------------------------
CONOUT_ESC_PROC:
        SBC A,A
        LD HL,$F3A2
        LD L,(HL)
        INC L
        JP Z,CONSOLE_PUT_CHAR
        LD HL,COL_FLAG
        LD (HL),A
        RES 7,C
        INC HL
        LD A,(HL)
        OR A
        JP Z,CONOUT_SEQ_MATCH
        DEC (HL)
; [DOC S&HD 2-14] Cursor-address coordinate handling: $F396 is SXYOFF, the Software cursor XY
;       coordinate offset (range 0-127; high bit 0 => Y first then X, high bit 1 => X first then Y).
        LD A,($F396)
        LD HL,BIOS_BOOT_1
        JR Z,COORD_SIGN_CHK
        OR A
        JP P,COORD_BIAS_SUB
        DEC HL
; ----------------------------------------------------------------------
; COORD_MASK7 -- apply a signed config offset to the running column position.
;   In:  A = config byte (sign bit = direction); C = current column; HL -> column cell.
;   Out: (HL) = C - offset.  Clobbers: A,E.
;   Algorithm: AND $7F drops the sign bit to the magnitude (COORD_BIAS_SUB entry skips
;     the mask), subtract it from C, store the new column. Twin of the 2.23-44K
;     COL_APPLY_OFFSET. [RE]
; ----------------------------------------------------------------------
COORD_MASK7:
        AND $7F
COORD_BIAS_SUB:
        LD E,A
        LD A,C
        SUB E
        LD (HL),A
        RET
COORD_SIGN_CHK:
        OR A
        JP M,COL_OFFSET_FROM_WIDTH
        DEC HL
; ----------------------------------------------------------------------
; COL_OFFSET_FROM_WIDTH -- derive the cursor screen coordinate and emit the move sequence.
;   In:  C = column; the BOOT-overlaid base word at (BIOS_BOOT+2).  Out: emits the
;     cursor-move via CONSOLE_PUT_CHAR.  Clobbers: A,B,C,DE,HL.
;   Algorithm: CALL COORD_MASK7 to fold the column, load the base word (BIOS_BOOT+2 =
;     the cold-boot LD SP operand reused as cursor scratch). [DOC S&HD 2-14] $F3A1 is
;     the Hardware cursor XY offset (counterpart of SXYOFF=$F396); its high bit selects
;     X/Y vs Y/X transmission order. Fold in the offset, ADD to form the address, emit
;     with B=7 then B=$0A (CHAR_C_TO_SCREEN). Twin of the 2.23-44K COL_OFFSET_FROM_WIDTH. [RE]
; ----------------------------------------------------------------------
COL_OFFSET_FROM_WIDTH:
        CALL COORD_MASK7
        LD HL,(BIOS_BOOT+2)
; [DOC S&HD 2-14] $F3A1 is the Hardware cursor XY coordinate offset (the hardware-table counterpart
;       of SXYOFF=$F396); its high bit likewise selects X/Y vs Y/X transmission order to the terminal.
        LD A,($F3A1)
        OR A
        JP P,EMIT_CURSOR_MOVE
        AND $7F
        LD E,L
        LD L,H
        LD H,E
EMIT_CURSOR_MOVE:
        LD E,A
        ADD A,H
        LD C,A
        LD A,E
        ADD A,L
        PUSH AF
        LD B,$07
        CALL CONSOLE_PUT_CHAR
        POP AF
        LD B,$0A
; ----------------------------------------------------------------------
; CHAR_C_TO_SCREEN -- tail: move A into C and tail-jump to the screen emitter.
;   In:  A = char/code, B = mode/count code.  Out: JP CONSOLE_PUT_CHAR (no return).
;   Clobbers: A,C.
;   Algorithm: LD C,A / JP CONSOLE_PUT_CHAR. Twin of the 2.23-44K CHAR_C_TO_SCREEN. [RE]
; ----------------------------------------------------------------------
CHAR_C_TO_SCREEN:
        LD C,A
        JP CONSOLE_PUT_CHAR
; ----------------------------------------------------------------------
; BIOS_SETSEC (SETSEC) -- set the requested sector for the next disk I/O.
;   In:  C = sector number.  Out: none.  Clobbers: A.
;   Algorithm: store C into the seksec cell BIOS_BOOT+1 ($FEEB = the cold-boot LD SP
;     operand low byte, reused post-boot as the requested-sector cell). The off-image
;     RWTS/deblock is the consumer; this image only WRITES it. Twin of the 2.23-44K
;     SETSEC. [RE]
; ----------------------------------------------------------------------
BIOS_SETSEC:
        LD A,C
        LD (BIOS_BOOT+1),A
        RET
; ----------------------------------------------------------------------
; BIOS_SETDMA (SETDMA) -- set the DMA (record transfer) address.
;   In:  BC = DMA buffer address (the 128-byte CP/M record source/destination).
;   Out: none.  Clobbers: none.
;   Algorithm: store BC into the dmaadr cell (DISK_DMAADR+2 = $FEFA, the operand region
;     of the cold-boot template store). The off-image deblock copy uses dmaadr as the
;     host<->record transfer endpoint. Twin of the 2.23-44K SETDMA. [RE]
; ----------------------------------------------------------------------
BIOS_SETDMA:
        LD (DISK_DMAADR+2),BC
        RET
        DEFS    88, $00                  ; fill
; ----------------------------------------------------------------------
; CONOUT_SEQ_MATCH -- scan the Software Screen Function Table for a control code.
;   In:  A/B = mode code; C = incoming char.  Out: emits a mapped function or the raw
;     char.  Clobbers: A,B,C,DE,HL.
;   Algorithm: read COL_STATE ($FEE6). [DOC S&HD 2-14/2-15] $F397 is SFLDIN, the Software
;     function lead-in char (0 = none); if set and it matches C, mark pending ($80) and
;     return; else control codes (<=$1F) fall into the SSFTAB scan (SEQ_TBL_SCAN),
;     printables emit directly via CONSOLE_PUT_CHAR. Twin of the 2.23-44K SETDMA_1. [RE]
; ----------------------------------------------------------------------
CONOUT_SEQ_MATCH:
        LD B,A
        LD HL,COL_STATE
        LD A,(HL)
        LD E,A
        OR A
        JR NZ,SEQ_TBL_SCAN
; [DOC S&HD 2-14/2-15] $F397 is SFLDIN, the Software function lead-in character (zero = no lead-in).
;       If set and it matches the incoming byte (in C), a lead-in has been consumed: marks pending
;       ($80) and returns; otherwise drops through to scan the Software Screen Function Table.
        LD A,($F397)
        OR A
        JR Z,SEQ_PRINTABLE_CHK
        CP C
        JR NZ,SEQ_PRINTABLE_CHK
        LD (HL),$80
        RET
SEQ_PRINTABLE_CHK:
        LD A,$1F
        CP C
        JP C,CONSOLE_PUT_CHAR
; [DOC S&HD 2-14/2-15] Scans the Software Screen Function Table for a matching control code. SSFTAB
;       (function #1) is at $F398; here HL=$F3A0 (function #9) and B=9 walks the 9 entries downward
;       to $F398, matching the incoming code against the 9 configurable screen functions. The
;       9-entry span $F398..$F3A0 implies fn#9 sits at $F3A0 (resolving the manual's fn8/fn9 ambiguity).
; ----------------------------------------------------------------------
; SEQ_TBL_SCAN -- match the incoming code against the 9 Software Screen Functions.
;   In:  C = control code, E = lead-in XOR mask.  Out: emits the matched function's
;     sequence or the raw char.  Clobbers: A,B,C,DE,HL.
;   Algorithm: [DOC S&HD 2-14/2-15] SSFTAB fn#1 is at $F398; HL=$F3A0 (fn#9), B=9 walks
;     the 9 entries downward to $F398, comparing each configured function code (XOR E)
;     against C. No match -> emit raw (CONSOLE_PUT_CHAR); match -> SEQ_EMIT_ENTRY. Twin
;     of the 2.23-44K SETDMA_3 SSFTAB scan. [RE]
; ----------------------------------------------------------------------
SEQ_TBL_SCAN:
        LD HL,$F3A0
        LD B,$09
CHECK_UNIT_DEFAULT_3:
        LD A,(HL)
        OR A
        JR Z,SEQ_TBL_NEXT
        XOR E
        CP C
        JR Z,SEQ_EMIT_ENTRY
SEQ_TBL_NEXT:
        DEC HL
        DJNZ CHECK_UNIT_DEFAULT_3
        JR CONSOLE_PUT_CHAR
; ----------------------------------------------------------------------
; SEQ_EMIT_ENTRY -- emit a matched screen function's replacement sequence.
;   In:  HL -> the matched SSFTAB entry; C carries state.  Out: emits via CONSOLE_PUT_CHAR;
;     may set the pending flag.  Clobbers: A,B,C,DE,HL.
;   Algorithm: index +$0B to the paired replacement byte; high bit set marks a hardware
;     lead-in ($F3A2, [DOC S&HD 2-14/2-15]) emitted ahead of the byte with B=7; then
;     SEQ_SET_PENDING may store $02 into COL_PENDING ($FEE5). Twin of the 2.23-44K
;     SETDMA_6/SETDMA_7. [RE]
; ----------------------------------------------------------------------
SEQ_EMIT_ENTRY:
        LD DE,$000B
        ADD HL,DE
        LD A,(HL)
        OR A
        LD C,A
        JP P,SEQ_SET_PENDING
        AND $7F
        LD C,A
        PUSH BC
; [DOC S&HD 2-14/2-15] Emits the matched function's Hardware-table lead-in: $F3A2 is the Hardware
;       lead-in character, sent ahead of the hardware screen-function byte to the terminal.
        LD A,($F3A2)
        LD B,$07
        CALL CHAR_C_TO_SCREEN
        POP BC
SEQ_SET_PENDING:
        LD A,B
        CP $07
        JR NZ,CONSOLE_PUT_CHAR
        LD A,$02
        LD (COL_PENDING),A
; [DOC S&HD 2-18/2-19] Console-output emit tail: loads HL from one of the two I/O Vector Table
;       Console Output cells -- $F388 (Console Output #2) if the mode flag at COL_FLAG is 0, else
;       $F386 (Console Output #1) -- and falls into the JP (HL). Output #1 serves TTY:/CRT:; Output
;       #2 serves UC1:. These are user-patchable cells that carry the char in C to the console device.
; ----------------------------------------------------------------------
; CONSOLE_PUT_CHAR -- emit tail: JP (HL) into the selected Console Output vector.
;   In:  C = character; COL_FLAG ($FEE4) selects the output cell.  Out: none (JP (HL)).
;   Clobbers: A,HL.
;   Algorithm: clear COL_STATE ($FEE6); load HL from one of the two I/O Vector Table
;     Console Output cells -- $F388 (Output #2, UC1:) if COL_FLAG is 0, else $F386
;     (Output #1, TTY:/CRT:) -- and JP (HL) (CONOUT_PHYS_JP). User-patchable cells that
;     carry the char in C to the console device. [DOC S&HD 2-18/2-19] Twin of the
;     2.23-44K SCREEN_EMIT. [RE]
; ----------------------------------------------------------------------
CONSOLE_PUT_CHAR:
        XOR A
        LD (COL_STATE),A
        LD A,(COL_FLAG)
        OR A
        LD HL,($F388)
        JR Z,CONOUT_PHYS_JP
        LD HL,($F386)
; [DOC S&HD 2-18/2-19] JP (HL) into the selected Console Output vector ($F386 #1 or $F388 #2)
;       resolved above -- the user-patchable I/O Vector Table cell that drives console output.
CONOUT_PHYS_JP:
        JP (HL)
        DEFB    $11,$03,$00,$C3
CONOUT_HANDLER_VEC:
        DEFB    $BB,$FC,$2A,$E7,$FE,$3A,$E9,$FE,$77,$CD,$E2,$FC,$2A,$28,$F0,$3A
        DEFB    $24,$F0,$5F,$16,$F0,$19,$22,$E7,$FE,$7E,$32,$E9
        DEFW    BIOS_BOOT_8
        DEFB    $E0,$38,$02,$EE,$20,$E6,$3F,$F6,$40,$77,$C9,$78,$B7,$28,$0B,$21
        DEFW    RPC_TRIGGER
        DEFB    $E5,$21,$66,$FD,$85,$6F,$6E,$E9
        DEFW    INIT_PASCAL_1_1_2
        DEFB    $0D,$20,$05,$AF,$32,$24,$F0,$C9,$F6
        DEFW    SETTRK_STORE
        DEFB    $E0,$38,$04,$21,$DD,$F3,$AE,$32,$45,$F0,$21,$F0,$FD,$C3,$80,$FD
        DEFB    $CD
        DEFW    SLOT_IO_ADDR
        DEFB    $C6,$8F,$CB,$4E,$28,$FC,$21,$2F,$F0,$36,$60,$2B,$36,$C0,$2B,$77
        DEFB    $2B,$36,$8D,$62,$C3,$7C,$FD,$3E,$FF,$01,$3E,$3F,$32,$32,$F0,$E1
        DEFB    $C9,$21
        DEFW    BIOS_SETSEC
        DEFB    $C9,$AF,$6F,$67,$22,$24,$F0,$32,$45,$F0,$21,$C1,$FB,$C9,$2E,$42
        DEFB    $01,$2E,$9C,$01,$2E,$1A,$01,$2E,$58,$26,$FC,$C9,$2A
        DEFW    BIOS_BOOT+2
        DEFB    $7D,$FE,$28,$38,$02,$2E,$00,$7C,$FE,$18,$38,$02,$26,$00,$22,$24
        DEFB    $F0,$18,$D5,$4C,$43,$46,$28,$2B,$36,$30,$49,$32,$51,$CD
        DEFW    INIT_PASCAL_1_0
        DEFB    $21,$78,$F6,$19,$71,$21,$AA,$C9,$79,$32,$45,$F0,$C3
        DEFW    RPC_TRIGGER
; [DOC S&HD 2-24/2-25] Card init that stages 6502 RPC register-pass cells before a SoftCard call:
;       $F047 is cell $47 (6502 X register pass area) and $F046 is cell $46 (6502 Y register pass
;       area). The full RPC set is $45=A, $46=Y, $47=X, $48=P, $49=6502 SP-on-exit (Y precedes X).
; ----------------------------------------------------------------------
; INIT_PASCAL_1_0 -- stage the 6502 RPC register-pass cells for a Videx-class card init.
;   In:  E = slot index.  Out: A = a card firmware byte; RPC cells staged.  Clobbers: A,HL.
;   Algorithm: CALL SLOT_IO_ADDR_W for the card I/O base; stash it in $F6F8 and RPC cell
;     $47 ($F047 = 6502 X pass area); read a card byte at $EFFF; SLOT_E000_ADDR + SUB $20
;     into RPC cell $46 ($F046 = 6502 Y pass area). [DOC S&HD 2-24/2-25] The full RPC set
;     is $45=A, $46=Y, $47=X, $48=P, $49=6502 SP-on-exit. Twin of the 2.23-44K
;     SET_SCREEN_BASE. [RE]
; ----------------------------------------------------------------------
INIT_PASCAL_1_0:
        CALL SLOT_IO_ADDR_W
        LD ($F6F8),A
        LD ($F047),A
        LD A,($EFFF)
        CALL SLOT_E000_ADDR
        SUB $20
        LD ($F046),A
        LD A,(HL)
        RET
CONST_SLOT3_TBL:
        DEFB    $21,$1D,$0E,$1E,$03,$3E,$01,$CD,$AD,$FD,$3A,$48,$F0,$1F,$9F,$C9
        DEFB    $21,$E1,$0D,$79,$32,$45,$F0
; [AI] Pascal-1.1 card initializer (the POST-1980 device-6 class the 2.20 manual does NOT cover).
;       [DOC S&HD 2-24/2-25] The cell it stages, $F047, is RPC cell $47 (6502 X register pass area);
;       it then triggers the SoftCard call via RPC_TRIGGER. The Pascal-1.1 / device-6 dispatch
;       itself is a 2.23-era extension, not manual-backed.
; ----------------------------------------------------------------------
; PLOT_CHAR_RPC -- Pascal-1.1 / device-6 card initializer (post-1980 class).
;   In:  E = a card parameter byte.  Out: fires the SoftCard call.  Clobbers: A.
;   Algorithm: store E into RPC cell $47 ($F047 = 6502 X register pass area,
;     [DOC S&HD 2-24/2-25]) then tail-jump to RPC_TRIGGER to run the 6502 service.
;     The device-6 / Pascal-1.1 dispatch is a 2.23-era extension the 2.20 manual does
;     NOT document. Twin of the 2.23-44K PLOT_CHAR_RPC family. [RE]
; ----------------------------------------------------------------------
PLOT_CHAR_RPC:
        LD A,E
        LD ($F047),A
        JP RPC_TRIGGER
        DEFB    $21,$0F,$0E,$CD
        DEFW    PLOT_CHAR_RPC
        DEFB    $3A,$45,$F0,$C9,$CD
        DEFW    INIT_PASCAL_1_0
        DEFB    $21,$4D,$C8,$CD
        DEFW    RPC_TRIGGER
        DEFB    $21,$78,$F6,$19,$7E,$C9,$48,$20,$26,$0E,$A0,$0D,$B1,$F6,$85,$F6
        DEFB    $AC,$F8,$06,$68,$6C,$F6,$00,$48,$A9,$00,$20,$EF,$0D,$20,$26,$0E
        DEFB    $A0,$0F,$4C,$D6,$0D,$84,$F5,$48,$20,$1D,$0E,$68,$A4,$F5,$90,$F5
        DEFB    $60,$00,$00,$00,$00,$00,$4C,$09,$0E,$8D,$8B,$C0,$4C,$13,$D4,$8D
        DEFB    $8B,$C0,$4C,$F7,$D1,$A9,$01,$20,$EF,$0D,$20,$26,$0E,$48,$A0,$0E
        DEFB    $4C,$D6,$0D,$48,$20,$26,$0E,$A0,$10,$4C,$D6,$0D,$98,$09,$C0,$AA
        DEFB    $98,$0A,$0A,$0A,$0A,$A8,$8C,$F8,$06,$A9,$00,$85,$F6,$86,$F7
        DEFW    BANNER_PUT_ATTR
        DEFB    $CF,$B1,$F6,$60,$A5,$48,$48,$A5,$45,$A6,$46,$A4,$47,$28,$58,$60
        DEFB    $CD
        DEFW    SLOT_IO_ADDR
        DEFB    $7E,$1F,$30,$FC,$2C,$7E,$C9,$11,$01,$00,$C3
READER_HANDLER_TBL:
        DEFB    $68,$FE,$CD
        DEFW    SLOT_E000_ADDR
        DEFB    $2E,$C1,$7E,$17,$38,$FC,$CD
        DEFW    SLOT_IO_ADDR_W
        DEFB    $71,$C9,$11,$02,$00,$C3
PUNCH_HANDLER_TBL:
        DEFB    $68,$FE,$11,$02,$00
AUX_DEV_STUB:
        DEFB    $C3
AUX_DEV_VEC:
        DEFB    $00
AUX_DEV_VEC_HI:
        DEFB    $00
; ----------------------------------------------------------------------
; INIT_PASCAL_1_1_1 (HOME) -- BIOS jump-vector entry 8: seek the drive to track 0.
;   In:  none.  Out: none (falls into SETTRK's store with track 0).  Clobbers: A,C.
;   Algorithm: read the host-write-pending template cell (DISK_HSTWRT); if a write is
;     pending keep the host-active flag, else clear DISK_HSTACT; then fall into
;     INIT_PASCAL_1_1_3/_4 (SETTRK) with track 0. The actual head step happens later in
;     the off-image deblock path. Twin of the 2.23-44K HOME/SETTRK_STORE. [RE]
; ----------------------------------------------------------------------
INIT_PASCAL_1_1_1:
        LD A,(DISK_HSTWRT)
        OR A
INIT_PASCAL_1_1_2:
        JR NZ,INIT_PASCAL_1_1_3
        LD (DISK_HSTACT),A
INIT_PASCAL_1_1_3:
        LD C,$00
; ----------------------------------------------------------------------
; SETTRK_STORE (SETTRK) -- BIOS jump-vector entry 10: set the requested track.
;   In:  C = track number.  Out: none.  Clobbers: A.
;   Algorithm: LD A,C then store into the sektrk cell BIOS_BOOT ($FEEA = the cold-boot
;     LD SP operand byte reused post-boot as sektrk). HOME enters this common tail with
;     track 0. Twin of the 2.23-44K SETTRK_STORE tail. [RE]
; ----------------------------------------------------------------------
SETTRK_STORE:
        LD A,C
        LD (BIOS_BOOT),A
        RET
; ----------------------------------------------------------------------
; SLOT_IO_ADDR_W -- map a slot/drive index to the Apple $C080 write/control-bank base.
;   In:  E = slot/drive index (0..15).  Out: HL = $E080 + (E<<4).  Clobbers: A,L.
;   Algorithm: load z80 $E080 = Apple $C080, then fall into the shared index scaler
;     (SLOT_IOBASE_CALC). Twin of the 2.23-44K SLOT_IO_ADDR_W. [RE]
; ----------------------------------------------------------------------
SLOT_IO_ADDR_W:
        LD HL,$E080
        JR SLOT_IO_SCALE_E
; ----------------------------------------------------------------------
; SLOT_IO_ADDR -- map a slot/drive index to the Apple $C08E slot-I/O base.
;   In:  E = slot/drive index (0..15).  Out: HL = $E08E + (E<<4).  Clobbers: A,L.
;   Algorithm: load z80 $E08E = Apple $C08E, then fall into the shared index scaler
;     (SLOT_IO_SCALE_E -> SLOT_IOBASE_CALC). Twin of the 2.23-44K SLOT_IO_ADDR. [RE]
; ----------------------------------------------------------------------
SLOT_IO_ADDR:
        LD HL,$E08E
SLOT_IO_SCALE_E:
        LD A,E
; ----------------------------------------------------------------------
; SLOT_IOBASE_CALC -- shift the index left by 4 and add to L (index a 16-byte block).
;   In:  A = index (via SLOT_IO_SCALE_E from E), L = base low byte.  Out: L += A*16;
;     A preserved.  Clobbers: A,L.
;   Algorithm: ADD A,A x4 (A*=16), PUSH AF, ADD A,L, LD L,A, POP AF, RET. Shared by
;     SLOT_IO_ADDR_W/_8E and by SELDSK (DPH-table index) and PROBE_DEVICES. Twin of the
;     2.23-44K SLOT_IO_SCALE. [RE]
; ----------------------------------------------------------------------
SLOT_IOBASE_CALC:
        ADD A,A
        ADD A,A
        ADD A,A
        ADD A,A
        PUSH AF
        ADD A,L
        LD L,A
        POP AF
        RET
; ----------------------------------------------------------------------
; SELDSK_IMPL_1 (SELDSK) -- BIOS jump-vector entry 9: select the disk drive.
;   In:  C = disk number (0-based).  Out: HL = DPH address for drive C, or HL=0 if out
;     of range.  Clobbers: A,DE,HL.
;   Algorithm: DE -> the sekdsk build site (BIOS_BOOT_2, an install-template cell reused
;     as disk-state scratch). Read the configured drive count from the SoftCard config
;     block (z80 $F3B8 = Apple $03B8, the Disk Count Byte); if C >= count return HL=0
;     (SELDSK_BAD_DRIVE). Else record the disk number, index DPH_TABLE by C*16 (CALL
;     SLOT_IOBASE_CALC), pull a per-drive disk-parameter byte and self-modify the install
;     template SECTOR_BLOCK_PATCH+1 with it. [DOC S&HD 2-26/2-27] Twin of the 2.23-44K SELDSK. [RE]
; ----------------------------------------------------------------------
SELDSK_IMPL_1:
        LD DE,BIOS_BOOT_2
        LD HL,CDISK_ADDR
        LD A,(SLOT_INFO_BASE)
        DEC A
        CP C
        JR C,SELDSK_BAD_DRIVE
        LD A,(HL)
        LD (DE),A
        INC DE
        LD A,C
        LD (DE),A
        LD HL,DPH_TABLE
        CALL SLOT_IOBASE_CALC
        PUSH HL
        LD DE,$000A
        ADD HL,DE
        LD E,(HL)
        INC HL
        LD D,(HL)
        LD HL,BDOS
        ADD HL,DE
        LD A,(HL)
        LD (SECTOR_BLOCK_PATCH+1),A
        POP HL
        RET
; ----------------------------------------------------------------------
; SELDSK_BAD_DRIVE -- out-of-range drive: return HL=0 (no DPH).
;   In:  DE -> sekdsk build site.  Out: HL=0.  Clobbers: A,L.
;   Algorithm: restore the prior sekdsk byte, then LD L,$00 signals an invalid drive to
;     the BDOS. Twin of the 2.23-44K SELDSK_BAD_DRIVE. [RE]
; ----------------------------------------------------------------------
SELDSK_BAD_DRIVE:
        LD A,(DE)
        LD (HL),A
        LD L,$00
        RET
; ----------------------------------------------------------------------
; SELDSK_IMPL_3 (READ) -- BIOS jump-vector entry 13: read one 128-byte record.
;   In:  sekdsk/sektrk/seksec/dmaadr previously set.  Out: A=0 ok / 1 error.
;   Algorithm: stash A at $E08B (a 6502-side RPC param cell = Apple $C08B), then OFF-IMAGE
;     tail-jump to the deblock/RWTS read core at $B247 (below the BIOS, in the 60K
;     system-image region). Unlike the 2.20 twin, the 2.23 BIOS does NOT carry the deblock
;     in-image; READ/WRITE delegate to the $B2xx host-sector routines. [RE]
; ----------------------------------------------------------------------
SELDSK_IMPL_3:
        LD ($E08B),A
        JP $B247
; ----------------------------------------------------------------------
; SELDSK_IMPL_4 (WRITE) -- BIOS jump-vector entry 14: write one 128-byte record.
;   In:  C = write type; sekdsk/sektrk/seksec/dmaadr previously set.  Out: A=0 ok / 1 error.
;   Algorithm: stash A at $E08B (Apple $C08B RPC param), then OFF-IMAGE tail-jump to the
;     deblock/RWTS write core at $B257 (60K system-image region below the BIOS). Same
;     off-image RWTS delegation as SELDSK_IMPL_3 (READ). [RE]
; ----------------------------------------------------------------------
SELDSK_IMPL_4:
        LD ($E08B),A
        JP $B257
        DEFB    $CD
        DEFW    RPC_TRIGGER
        DEFB    $32,$8B,$E0,$C9,$32,$83,$E0,$2A,$0D,$DC,$E9,$32,$83,$E0,$C9
COL_FLAG:
        DEFB    $00
COL_PENDING:
        DEFB    $00
COL_STATE:
        DEFB    $00,$E9,$FE,$00
; ----------------------------------------------------------------------
; BIOS_BOOT -- Z-80 cold-boot init: runs ONCE, then self-modifies ~a few dozen bytes.
;   In:  entered once at cold start (the 60K reset-plant JPs here).  Out: enters the CCP
;     via the sign-on tail; never re-executed.  Clobbers: all.
;   Algorithm: set SP=$0100; NOP the $FA00 cold JP; load the default IOBYTE_ADDR ($95) into
;     $0003; bind Z$CPU ($F3DE) into RPC_TRIGGER_STORE+1; clear CDISK_ADDR; install console/list/
;     punch/reader handlers by Card Type Table class (device-6=Pascal-1.1, 5=parallel,
;     4=Videx patches the status vector); re-run PROBE_DEVICES; clear screen; print banner.
;   DUAL USE: the 'LD SP,$0100' operand bytes are reused post-boot as sektrk (BIOS_BOOT),
;     seksec (BIOS_BOOT+1) and a cursor word (BIOS_BOOT+2). After it runs, $FEEA-$FF8D is
;     dead scratch; the ~6 self-mods are cataloged in ../BOOT_AND_PATCHING.md section 3c.
;     [DOC S&HD 2-24/2-25, 2-26/2-27] Twin of the 2.23-44K install engine. [RE]
; ----------------------------------------------------------------------
BIOS_BOOT:
        LD SP,TPA
BIOS_BOOT_1:
        XOR A
BIOS_BOOT_2:
        LD HL,BOOT
DISK_HSTACT:
        LD (HL),A
DISK_HSTWRT:
        INC HL
        LD (HL),A
        INC HL
        LD (HL),A
BOOT_TMPL_IOBYTE:
        LD A,$95
DISK_DMAADR:
        LD (IOBYTE_ADDR),A
; [DOC S&HD 2-24/2-25] Loads the SoftCard location from Z$CPU=$F3DE and binds it into the RPC
;       dispatcher (patching RPC_TRIGGER_STORE+1) so subsequent 6502 calls switch via the right slot.
SECTOR_BLOCK_PATCH:
        LD HL,($F3DE)
BIOS_BOOT_8:
        LD (RPC_TRIGGER_STORE+1),HL
        XOR A
        LD (CDISK_ADDR),A
; [DOC S&HD 2-26/2-27] Reads the slot-3 (console) Card Type Table entry at $F3BB ($F3B8+3). [AI] The
;       CP $06 test selects the POST-1980 device-6 / Pascal-1.1 console class (a 2.23 extension the
;       2.20 manual does NOT document; in 2.20 the Videx is type 4). On a match it points the
;       [DOC S&HD 2-18] I/O Vector Table Console Status cell ($F380) at the slot-3 console handler.
        LD A,($F3BB)
        CP $06
        JR NZ,DEV_INSTALL_LIST
        LD HL,CONST_SLOT3_TBL
        LD ($F380),HL
        SUB $03
        JR DEV_INSTALL_PUNCH
; [DOC S&HD 2-26/2-27] Non-device-6 console path: dispatches on the slot-3 Card Type value. Value 5
;       (Apple Parallel Printer) skips ahead; values >=3 (serial / Videx-class / device-4) fall
;       through to install the console handlers; value 4 patches the slot-3 console-status vector below.
DEV_INSTALL_LIST:
        CP $05
        JR Z,BIOS_BOOT_11
        SUB $03
        JR C,BIOS_BOOT_11
        JR NZ,DEV_INSTALL_PUNCH
        LD HL,CONST_VEC_PATCH
        LD (HL),$BE
        INC HL
        INC HL
        LD (HL),$1F
DEV_INSTALL_PUNCH:
        PUSH AF
        CALL DEV_HANDLER_LOOKUP
        POP AF
        LD (CONOUT_HANDLER_VEC),HL
        CALL GET_CONIN_HANDLER
        LD (CONIN_HANDLER_VEC),HL
        LD A,$03
        LD (CCP_LAUNCH+1),A
; [DOC S&HD 2-26/2-27] Reads the slot-1 Card Type Table entry at $F3B9 (SLTTYP base = slot 1, per
;       Slot Function Assignments the LST: line-printer slot). For a recognized output card (value
;       >=3 after SUB $03) it resolves and installs that card's output handler for the list device.
BIOS_BOOT_11:
        LD A,($F3B9)
        SUB $03
        JR C,INSTALL_DONE_DEVICES
        CALL DEV_HANDLER_LOOKUP
        LD (READER_HANDLER_TBL),HL
; [DOC S&HD 2-26/2-27] Reads the slot-2 Card Type Table entry at $F3BA ($F3B8+2) -- per Slot
;       Function Assignments the general-purpose PUN:/RDR: slot. For a recognized output card it
;       installs the punch handler; the value also drives the reader-handler selection below.
INSTALL_DONE_DEVICES:
        LD A,($F3BA)
        SUB $03
        JR C,BIOS_BOOT_14
        PUSH AF
        CALL DEV_HANDLER_LOOKUP
        LD (PUNCH_HANDLER_TBL),HL
        POP AF
BIOS_BOOT_13:
        CP $02
        JR Z,BIOS_BOOT_14
        CALL GET_CONIN_HANDLER
        LD (AUX_DEV_VEC),HL
        JR BIOS_BOOT_15
BIOS_BOOT_14:
        LD HL,$1A3E
        LD (AUX_DEV_STUB),HL
        LD A,$C9
        LD (AUX_DEV_VEC_HI),A
; [DOC S&HD 2-14/2-15] Rescans the slots, then reads $F398 -- SSFTAB function #1, Clear Screen, the
;       first entry of the Software Screen Function Table -- and emits it to home/clear the console
;       before printing the sign-on banner.
BIOS_BOOT_15:
        CALL PROBE_DEVICES
        LD A,($F398)
        CALL BANNER_PUT_CHAR
        LD HL,SIGNON_BANNER
SIGNON_BANNER_LOOP:
        LD A,(HL)
        OR A
BIOS_BOOT_17:
        JP Z,PAGEZERO_REBUILD_HOOKS
        PUSH HL
        CALL CONOUT_SET_C
        POP HL
        INC HL
        JR SIGNON_BANNER_LOOP
CONOUT_VEC_TABLE:
        DEFB    $0E,$FD,$71,$FD,$5B,$FE,$A9,$FD
CONIN_VEC_TABLE:
        DEFB    $4B,$FE,$C1,$FD,$B7,$FD,$B7,$FD
; ----------------------------------------------------------------------
; GET_CONIN_HANDLER -- fetch a console-input handler address from CONIN_VEC_TABLE.
;   In:  A = card-class index (0-based).  Out: HL = handler address.  Clobbers: A,HL.
;   Algorithm: HL = CONIN_VEC_TABLE base, then fall into the shared index tail
;     (HANDLER_TBL_INDEX: HL += A*2; load the word). Twin of the 2.23-44K
;     DEV_HANDLER_LOOKUP_B family. [RE]
; ----------------------------------------------------------------------
GET_CONIN_HANDLER:
        LD HL,CONIN_VEC_TABLE
        JR HANDLER_TBL_INDEX
; ----------------------------------------------------------------------
; DEV_HANDLER_LOOKUP -- fetch a console-output handler address from CONOUT_VEC_TABLE.
;   In:  A = card-class index (0-based).  Out: HL = handler address.  Clobbers: A,HL.
;   Algorithm: HL = CONOUT_VEC_TABLE base, fall into HANDLER_TBL_INDEX (HL += A*2; load
;     the 16-bit word low-then-high). Twin of the 2.23-44K DEV_HANDLER_LOOKUP. [RE]
; ----------------------------------------------------------------------
DEV_HANDLER_LOOKUP:
        LD HL,CONOUT_VEC_TABLE
HANDLER_TBL_INDEX:
        ADD A,A
HANDLER_TBL_FETCH:
        ADD A,L
        LD L,A
        LD A,(HL)
        INC L
        LD H,(HL)
        LD L,A
        RET
; [AI] Banner character emitter: if the byte is positive (high bit clear) it outputs it directly; if
;       negative it first emits the software lead-in. [DOC S&HD 2-14/2-15] $F397 is SFLDIN, the
;       Software function lead-in character, sent ahead of the byte for the high-bit-set case.
; ----------------------------------------------------------------------
; BANNER_PUT_CHAR -- emit one sign-on byte, optionally preceded by a lead-in char.
;   In:  A = byte/flag.  Out: prints via CONOUT_SET_C.  Clobbers: A,HL.
;   Algorithm: if A is positive (bit7 clear) tail-jump to emit it directly
;     (BANNER_EMIT_CHAR); if negative, first emit the software lead-in char from config
;     $F397 (SFLDIN, [DOC S&HD 2-14/2-15]) via CONOUT_SET_C, then emit A. Twin of the
;     2.23-44K SIGNON_EMIT. [RE]
; ----------------------------------------------------------------------
BANNER_PUT_CHAR:
        OR A
        JP P,BANNER_EMIT_CHAR
        PUSH AF
BANNER_PUT_ATTR:
        LD A,($F397)
        CALL CONOUT_SET_C
BANNER_RESTORE_A:
        POP AF
BANNER_EMIT_CHAR:
        JP CONOUT_SET_C
; [AI] Cold-boot sign-on banner emitted by the loop above: "Softcard CP/M / 60K Ver. 2.23 / (c)
;       1980,1982 Microsoft". This is the POST-1980 60K / 2.23 variant; the 2.20 manual documents only
;       the "APPLE II CP/M / 44K vers. 2.2X / (C) 1980 MICROSOFT" 44K/56K banner (S&HD 1-8), so the
;       "60K"/"2.23"/"1982" tokens here are version-specific, not manual-backed.
SIGNON_BANNER:
        DEFB    $0D,$0A,$0A,$0A,$20,$20,$20,$20,$20,$53,$6F,$66,$74,$63,$61,$72
        DEFB    "d CP/M"                 ; string
        DEFB    $0D                      ; terminator
        DEFB    $0A,$20,$20,$20,$20,$20,$36,$30,$4B,$20,$56,$65,$72,$2E,$20,$32
        DEFB    $2E,$32,$33,$0D,$0A,$28,$63,$29,$20,$31,$39,$38,$30,$2C,$31,$39
        DEFB    "82 Microsoft"           ; string
        DEFB    $0D                      ; terminator
        DEFB    $0A,$0D,$0A
        DEFW    BOOT

BIOS_IMAGE_END:                          ; first byte past the BIOS image (wraps $10000->$0000)

    IFNDEF CPM60_LINK  ; [link] master defines CPM60_LINK and owns this; standalone keeps it
    ; Image size from its bracketing labels, not a magic length, as in the 2.23-44K twin:
    ; an overrun fails the build here instead of being silently truncated by SAVEBIN.
    ; $FA00 = the ORG base; the subtraction wraps because the image ends at $10000.
    SAVEBIN "CPM_BIOS.bin", $FA00, BIOS_IMAGE_END - $FA00
    ENDIF

; ----------------------------------------------------------------------
; BDOS scratch overlay -- the SECOND tenant of $FEFD-$FFF4.
;   Those bytes are the one-shot cold-boot / sign-on code above (the region the file
;   header describes as dead after BIOS_BOOT has run). It runs once at cold start; only
;   afterwards does the disk system reuse them as the buffers DPH_TABLE hands out. The
;   two tenants are never live at the same time.
;
;   The region is declared here as a LAYOUT, not as a set of magic addresses: one ORG
;   at the overlay base, then one label per field with its extent carried in the
;   arithmetic that advances to the next. Labels emit no bytes, so this names the
;   region without writing to it -- the cold-boot code above still owns every byte of
;   the image. Under the CPM60.COM master link this file is assembled inside a
;   DISP $FA00 block, where sjasmplus moves only the displacement address and leaves
;   the physical output pointer alone, so the ORGs are safe there too.
;
;   Reference whichever tenant is live at the point of use: the cold-boot routines by
;   their own labels, and these names from DPH_TABLE, which the BDOS reads long after
;   cold boot has finished. Same shape and names as the 2.20-44K and 2.23-44K twins;
;   only the addresses differ. [RE]
; ----------------------------------------------------------------------
DRIVES       EQU 4                    ; four DPH entries in DPH_TABLE
DIRBUF_SIZE  EQU 128                  ; one 128-byte directory record
ALV_SIZE     EQU 139 / 8 + 1          ; = 18; 139 is DSM, the highest allocation block number
CSV_SIZE     EQU 12                   ; = CKS

        ORG $FEFD                     ; the one given: where the author placed the overlay
DIRBUF:                               ; shared directory buffer, one per system
        ORG DIRBUF + DIRBUF_SIZE
ALV_VECTORS:                          ; per-drive allocation vectors ($FF7D..)
        ORG ALV_VECTORS + DRIVES * ALV_SIZE
CSV_VECTORS:                          ; per-drive checksum vectors ($FFC5..)
        ORG CSV_VECTORS + DRIVES * CSV_SIZE
BIOS_SCRATCH_END:                     ; first byte past the overlay ($FFF5)

    ; Pin the derived layout to the addresses the shipped image actually uses: change
    ; DRIVES or a size and the build fails here rather than silently moving a buffer.
    ASSERT ALV_VECTORS == $FF7D
    ASSERT CSV_VECTORS == $FFC5
    ASSERT BIOS_SCRATCH_END == $FFF5
